def reclaim_qualifies(f,d):
    if d['kind'] not in ('RECLAIM','COMBINED'):return False
    return f['reclaim'+str(d['lookback'])] and f['body_atr']>=d['body'] and (d['close'] is None or f['close_location']>=d['close'])

def study_qualifies(f,d):
    primary=comparator_qualifies(f,FROZEN_ENTRIES[0])
    if d['kind']=='PRIMARY':return primary
    frequency=comparator_qualifies(f,FROZEN_ENTRIES[1])
    if d['kind']=='FREQUENCY':return frequency
    if d['kind']=='VOL_COMPARATOR':return primary or (frequency and f['h4_atr_ratio'] is not None and f['h4_atr_ratio']<=1.10)
    return (primary or reclaim_qualifies(f,d)) if d['kind']=='COMBINED' else reclaim_qualifies(f,d)

def study_features(bars,atrs,engulf):
    found={}
    for i in range(200,len(bars)):
        p=bars[i]['mid'];a=atrs[i];r=p['h']-p['l']
        if p['c']<=p['o'] or r<=0 or a is None or a<=0:continue
        levels={l:min(b['mid']['l'] for b in bars[i-l:i]) for l in TRIGGER_LB}
        reclaim={l:p['l']<v and p['c']>v for l,v in levels.items()}
        if i not in engulf and not any(reclaim.values()):continue
        f=dict(engulf[i]) if i in engulf else {'atr':a,'body_atr':(p['c']-p['o'])/a,'range_atr':r/a,'close_location':(p['c']-p['l'])/r,'body_ratio':(p['c']-p['o'])/r,'distances':{l:abs(p['l']-min(b['mid']['l'] for b in bars[i-l:i]))/a for l in LB},'h4_atr_ratio':a/(sum(atrs[i-60:i])/60)}
        f['exact_engulf']=i in engulf
        for l,v in levels.items():
            f['prior_low'+str(l)]=v;f['reclaim'+str(l)]=reclaim[l];f['penetration_atr'+str(l)]=(v-p['l'])/a
        found[i]=f
    return found

def independent_mechanism_masks(bars,definitions=None):
    if definitions is None:definitions=DEFINITIONS
    masks={d['id']:[] for d in definitions};audit={};atrs=[None]*len(bars);seed=[];atr=None
    for i in range(1,len(bars)):
        p=bars[i]['mid'];q=bars[i-1]['mid'];tr=max(p['h']-p['l'],abs(p['h']-q['c']),abs(p['l']-q['c']))
        if i<=14:seed.append(tr)
        if i==14:atr=sum(seed)/14
        elif i>14:atr=(13*atr+tr)/14
        atrs[i]=atr
        if i<200 or p['c']<=p['o'] or p['h']<=p['l'] or atr is None or atr<=0:continue
        lows={l:min(b['mid']['l'] for b in bars[i-l:i]) for l in TRIGGER_LB}
        rec={l:p['l']<low and p['c']>low for l,low in lows.items()}
        exact=q['c']<q['o'] and p['o']<=q['c'] and p['c']>=q['o'] and q['h']>q['l']
        if not exact and not any(rec.values()):continue
        ba=(p['c']-p['o'])/atr;ra=(p['h']-p['l'])/atr;cl=(p['c']-p['l'])/(p['h']-p['l'])
        strength=exact and ba>=1.40 and ra>=1.50 and (p['c']-p['o'])/(p['h']-p['l'])>=.60
        primary=strength and abs(p['l']-lows[40])/atr<=.50;frequency=strength and abs(p['l']-lows[20])/atr<=.50
        vol=atr/(sum(atrs[i-60:i])/60)
        audit[i]={'atr':atr,'primary':primary,'frequency':frequency,'exact_engulf':exact,'reclaims':rec,'levels':lows}
        for d in definitions:
            if d['kind']=='PRIMARY':keep=primary
            elif d['kind']=='FREQUENCY':keep=frequency
            elif d['kind']=='VOL_COMPARATOR':keep=primary or frequency and vol<=1.10
            else:
                selected=rec[d['lookback']] and ba>=d['body'] and (d['close'] is None or cl>=d['close'])
                keep=primary or selected if d['kind']=='COMBINED' else selected
            if keep:masks[d['id']].append(i)
    return masks,audit

